    "key_characteristics": "co-infection with HBV and HIV transmitted perinatally; previous prolonged and intermittent treatment with lamivudine and tenofovir; HBV resistant to lamivudine; clinical resistance to tenofovir with HBV-DNA breakthrough; non-compliance excluded; HIV-RNA constantly suppressed"
  },
  "intervention": {
    "name": "entecavir added to tenofovir and emtricitabine",
    "dose": "entecavir 1 mg daily; tenofovir and emtricitabine doses not specified",
